function minOperations(nums) {
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) ?? 0) + 1);
  }

  let operations = 0;
  for (const freq of count.values()) {
    if (freq === 1) {
      return -1;
    }
    operations += Math.ceil(freq / 3);
  }
  return operations;
}

