function minOperations(nums) {
  // Sort to group equal values, then solve each group size with a small DP over removals of 2 or 3.
  const sorted = [...nums].sort((a, b) => a - b);
  const best = [0, Infinity];
  let total = 0;
  for (let i = 0; i < sorted.length;) {
    let j = i;
    while (j < sorted.length && sorted[j] === sorted[i]) j++;
    const size = j - i;
    for (let k = best.length; k <= size; k++) best.push(Math.min(best[k - 2], k >= 3 ? best[k - 3] : Infinity) + 1);
    if (best[size] === Infinity) return -1;
    total += best[size];
    i = j;
  }
  return total;
}

