function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 11);
  const nums = [];
  if (size === 'small' && rand() < 0.5) {
    // A narrow value range gives random group sizes, sometimes 1.
    const span = 1 + Math.floor(rand() * 5);
    while (nums.length < n) nums.push(1 + Math.floor(rand() * span));
  } else {
    // Build groups of equal values; a group of one (which makes the answer -1) is rare.
    const used = new Set();
    while (nums.length < n) {
      let value;
      do { value = 1 + Math.floor(rand() * 1000000); } while (used.has(value));
      used.add(value);
      let group = rand() < 0.05 ? 1 : 2 + Math.floor(rand() * (size === 'large' ? 40 : 6));
      group = Math.min(group, n - nums.length);
      for (let k = 0; k < group; k++) nums.push(value);
    }
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
